import { TaxTable } from './TaxTable';

export interface InvoiceLine {
  sku: string;
  quantity: number;
  unitPrice: number;
  kind: 'charge' | 'credit';
}

export class InvoiceCalculator {
  constructor(private readonly taxes: TaxTable) {}

  computeTotal(lines: InvoiceLine[], region: string): number {
    let total = 0;
    for (const line of lines) {
      if (line.quantity === 0) {
        continue;
      }
      const rate = this.taxes.rateFor(region, line.sku);
      let amount = line.quantity * line.unitPrice;
      if (line.kind === 'credit') {
        amount = -amount;
      } else if (amount < 0) {
        throw new Error('negative charge');
      }
      // round per line, not per invoice
      amount = Math.round(amount * (1 + rate) * 100) / 100;
      total += amount;
    }
    return total;
  }

  applyDiscount(total: number, percent: number): number {
    // discount is capped at 50 percent
    return total - (total * Math.min(percent, 50)) / 100;
  }
}

