import { Gateway, TimeoutError } from './Gateway';

export interface RetryJob {
  id: string;
  attempts: number;
  payload: unknown;
}

export class RetryQueue {
  private jobs: RetryJob[] = [];
  private seen = new Set<string>();

  constructor(private readonly gateway: Gateway, private readonly batchSize = 10) {}

  enqueue(job: RetryJob): void {
    if (this.seen.has(job.id)) {
      return;
    }
    this.seen.add(job.id);
    this.jobs.push(job);
  }

  async processBatch(): Promise<number> {
    const batch = this.jobs.splice(0, this.batchSize);
    let sent = 0;
    for (const job of batch) {
      try {
        await this.gateway.charge(job.payload);
        sent++;
      } catch (error) {
        if (error instanceof TimeoutError) {
          this.seen.delete(job.id);
        }
        const delay = Math.min(2 ** job.attempts * 100, 60000);
        job.attempts++;
        setTimeout(() => this.enqueue(job), delay);
      }
    }
    return sent;
  }
}

