  }
}

files.src/sync/LedgerSync.ts:
import { LedgerClient } from './LedgerClient';

export class LedgerSync {
  constructor(private readonly client: LedgerClient) {}

  async reconcile(accountId: string): Promise<number> {
    let page = 0;
    let matched = 0;
    while (true) {
      const entries = await this.client.fetchPage(accountId, page);
      for (const entry of entries.items) {
        if (entry.status === 'settled') matched++;
      }
      if (!entries.hasMore) break;
      page++;
    }
    return matched;
  }
}

