export class TaxTable {
  constructor(private readonly rates: Record<string, number>) {}

  rateFor(region: string, sku?: string): number {
    const key = sku ? `${region}:${sku}` : region;
    return this.rates[key] ?? this.rates[region] ?? 0;
  }
}

